// frontend/src/components/graph/cosmosMaps.ts
/**
 * Brightness and colour maps of the real objects the opening journey's
 * figures are drawn from. Generated, not hand-written: each is a photograph
 * with its stars removed, background subtracted, asinh-stretched, sharpened
 * and downsampled. cosmos.ts samples particle positions from the brightness
 * (density) map and their colours from the colour map, so the dust lands
 * where the gas really is.
 *
 * Sources (only these low-resolution derived maps ship, not the images):
 *   orion     — M42, image credited HG731GZ in Stellarium's DSO textures (github.com/Stellarium/stellarium)
 *   helix     — NGC 7293, ESO/VISTA/J. Emerson, eso.org/public/images/eso1205a (CC BY 4.0)
 *   butterfly — NGC 6302, NASA, ESA and the Hubble SM4 ERO Team (CC BY 4.0)
 *   galaxy    — M74, Bart Delsaert (via Stellarium's DSO textures, GPL)
 *
 * Layout: `d` is w×h bytes, row-major from the top-left; `c` is cw×ch RGB
 * triplets. The galaxy packs density into the top 6 bits and a class into
 * the low 2 (0 bulge, 1 arm, 2 inter-arm haze, 3 star-forming knot); `R` is
 * the disk radius as a fraction of the map's half-width.
 */
export type CosmosMap = { w: number; h: number; d: string; cw?: number; ch?: number; c?: string; R?: number };

export const ORION_MAP: CosmosMap = {"w": 150, "h": 150, "d": "", "cw": 50, "ch": 50, "c": ""};
export const HELIX_MAP: CosmosMap = {"w": 150, "h": 150, "d": "", "cw": 50, "ch": 50, "c": ""};
export const BUTTERFLY_MAP: CosmosMap = {"w": 170, "h": 103, "d": "", "cw": 56, "ch": 34, "c": ""};
export const GALAXY_MAP: CosmosMap = {"w": 200, "h": 200, "d": "", "R": 0.7186105349786478};
